// Body prose for the three villa landing pages added after the apartment and
// cluster pages:
//   new-build-villas-estepona.html
//   new-build-villas-marbella.html
//   new-build-villas-costa-del-sol.html
//
// Same contract as segment_page_translations.mjs and
// segment_page_translations_clusters.mjs: literal find/replace over the
// already-rendered English HTML, so `find` carries the entities esc() produced
// and the *Html fields are copied verbatim from the source in
// build_segment_pages.mjs.
//
// Titles and H1s keep a literal {count}, resolved after this table has run.
// Every title puts the number in a parenthetical, so a language that would have
// to decline a noun after it (Russian, Polish, Arabic) states it as
// "(в наличии: {count})" and the whole parenthetical goes when the count is
// below the display threshold.
//
// Vocabulary is the site's own, read from the entries already in the repo, not
// chosen here: "semi-detached" is casas pareadas / maisons jumelées /
// Doppelhaushälften / halfvrijstaande woningen / domy bliźniacze / parhus /
// tomannsboliger, the Golden Triangle is El Triángulo de Oro / Das Goldene
// Dreieck / De Gouden Driehoek / Den gyllene triangeln, and the two Andalucian
// taxes are written the way guide-purchase-costs-andalucia.html writes them
// (percentages with no space, a decimal comma everywhere but Arabic).
//
// Registers: usted, vous, Sie, u, Państwo / impersonal, ni (Swedish), du
// (Norwegian, where "De" is archaic), and the formal Russian "вы".
//
// The two paragraphs below the stats panel, the delivery and tax FAQ answers
// and the "what varies most" fact are shared by all three pages, so each is
// authored once.
const E = (find, es, fr, de, ru, ar, nl, pl, sv, no) => ({ find, es, fr, de, ru, ar, nl, pl, sv, no });

